// arc_src.h is generated by run_tests.sh from the real Marlin_main.cpp and motion_control.cpp
#include "arc_src.h"
#include <assert.h>
int main()
{
  recalc_delta_settings(delta_radius, delta_diagonal_rod);
  // 1. reachable <=> calculate_delta gives no NaN, on a fine grid far beyond the printable area
  int mism = 0, n = 0, out = 0;
  for (float x = -299.9; x <= 300; x += 2.5)
    for (float y = -299.9; y <= 300; y += 2.5)
      for (float z = 0; z <= 250; z += 125) {
        float c[3] = {x, y, z};
        calculate_delta(c);
        bool nan = isnan(delta[0]) || isnan(delta[1]) || isnan(delta[2]);
        bool r = delta_reachable(c);
        n++;
        if (!r) out++;
        if (nan == r) mism++;
      }
  printf("reachable() vs NaN: %d points (%d outside the reach), mismatches: %d\n", n, out, mism);
  assert(mism == 0 && out > 0);
  // 2. an arc that stays inside is planned completely with the Cartesian length of every segment
  float pos[4] = {30, 0, 10, 0}, tgt[4] = {0, 30, 10, 5}, off[4] = {-30, 0, 0, 0};
  mc_arc(pos, tgt, off, X_AXIS, Y_AXIS, Z_AXIS, 50, 30, 0, 0);
  double tot = 0;
  for (auto &s : segs) tot += s.len;
  printf("arc inside: %zu segments, total Cartesian length %.3f mm (a quarter circle of r=30 is %.3f), E at end %.3f (target %.3f)\n", segs.size(), tot, M_PI / 2 * 30, segs.back().e, tgt[3]);
  assert(fabs(tot - M_PI / 2 * 30) < 0.1 && fabs(segs.back().e - tgt[3]) < 1e-4);
  // 3. an arc that leaves the reachable area is stopped: target (the parser position) becomes the last planned point
  segs.clear();
  float pos2[4] = {40, 0, 10, 0}, tgt2[4] = {160, 0, 10, 8}, off2[4] = {60, 0, 0, 0};  // circle of radius 100 around the origin, starting near the edge
  float c0[3] = {40, 0, 10};
  printf("start (40,0,10) reachable: %d\n", delta_reachable(c0));
  mc_arc(pos2, tgt2, off2, X_AXIS, Y_AXIS, Z_AXIS, 50, 60, 0, 0);
  assert(segs.size() > 0 && segs.size() < 315);
  printf("arc through the edge: %zu segments planned, parser position now (%.2f, %.2f, %.2f) E %.3f\n", segs.size(), tgt2[0], tgt2[1], tgt2[2], tgt2[3]);
  {
    float e[3] = {tgt2[0], tgt2[1], tgt2[2]};
    printf("parser position reachable: %d\n", delta_reachable(e));
    assert(delta_reachable(e) && tgt2[3] > 0 && tgt2[3] < 8);
  }
  if (!segs.empty()) {
    float last[3] = {segs.back().c[0], segs.back().c[1], segs.back().c[2]};
    (void)last;
  }
  puts("arcs and reach OK");
  return 0;
}
